// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, address actor) public {
        vm.assume(actor != address(0));
        t1 = bound(t1, 1, type(uint256).max - 2);

        vm.deal(actor, 20 ether);
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first admissible call must succeed");

        // General rule: a successful call at t records pastBlockTime = t + 1,
        // so an immediate retry at exactly t + 1 is rejected (needs a strictly
        // later timestamp). The mutant records t, so the retry succeeds.
        vm.warp(t1 + 1);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "call at t+1 must be rejected (cooldown of 2 seconds)");
    }
}
